export function useLockContract() {
  const { address: account, chainId } = useAccount();
  const { data: client } = useConnectorClient();
  const { writeContract, data: writeData, isPending: isWritePending, error: writeError } = useWriteContract();
  const { isLoading: isConfirming, isSuccess, error: receiptError } = useWaitForTransactionReceipt({
    hash: writeData
  });
  const supportsEip5792 = useEip5792Support(chainId);
  const abxToken = ABX_TOKENS[chainId] || ABX_TOKENS[UniverseChainId.Mainnet];
  const VOTING_ESCROW_ADDRESS = useMemo(() => {
    const contracts = getAbstractContracts(chainId);
    return contracts?.votingEscrow;
  }, [chainId]);
  const { data: abxBalance } = useReadContract({
    address: abxToken.address,
    abi: ERC20_ABI,
    functionName: "balanceOf",
    args: account ? [account] : void 0
  });
  const { data: abxAllowance, refetch: refetchAllowance } = useReadContract({
    address: abxToken.address,
    abi: ERC20_ABI,
    functionName: "allowance",
    args: account ? [account, VOTING_ESCROW_ADDRESS] : void 0
  });
  const { data: lockCount, refetch: refetchLockCount } = useReadContract({
    address: VOTING_ESCROW_ADDRESS,
    abi: VOTING_ESCROW_ABI,
    functionName: "balanceOf",
    args: account ? [account] : void 0
  });
  const approveABX = useCallback(async (amount) => {
    const maxAmount = BigInt("0xffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff");
    return writeContract({
      address: abxToken.address,
      abi: ERC20_ABI,
      functionName: "approve",
      args: [VOTING_ESCROW_ADDRESS, maxAmount]
    });
  }, [writeContract, abxToken]);
  const createLockBatched = useCallback(async ({ amount, lockDurationInDays }) => {
    if (!account || !client || !chainId) {
      throw new Error("Wallet not connected");
    }
    const amountBigInt = parseUnits(amount, abxToken.decimals);
    const currentDate = /* @__PURE__ */ new Date();
    const daysUntilNextEpoch = getDaysUntilNextEpoch(currentDate);
    let epochs;
    if (lockDurationInDays <= daysUntilNextEpoch) {
      epochs = 1;
    } else {
      const daysAfterFirstEpoch = lockDurationInDays - daysUntilNextEpoch;
      const additionalEpochs = Math.ceil(daysAfterFirstEpoch / 7);
      epochs = 1 + additionalEpochs;
    }
    const SECONDS_PER_WEEK = 7 * 24 * 60 * 60;
    const lockDurationInSeconds = BigInt(epochs * SECONDS_PER_WEEK);
    const maxAmount = BigInt("0xffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff");
    const approveCalldata = encodeFunctionData({
      abi: ERC20_ABI,
      functionName: "approve",
      args: [VOTING_ESCROW_ADDRESS, maxAmount]
    });
    const createLockCalldata = encodeFunctionData({
      abi: VOTING_ESCROW_ABI,
      functionName: "createLock",
      args: [amountBigInt, lockDurationInSeconds]
    });
    const result = await client.request({
      method: "wallet_sendCalls",
      params: [{
        version: "2.0.0",
        chainId: `0x${chainId.toString(16)}`,
        from: account,
        calls: [
          {
            to: abxToken.address,
            data: approveCalldata,
            value: "0x0"
          },
          {
            to: VOTING_ESCROW_ADDRESS,
            data: createLockCalldata,
            value: "0x0"
          }
        ]
      }]
    });
    return result.id;
  }, [writeContract, account, client, chainId, abxToken]);
  const createLock = useCallback(async ({ amount, lockDurationInDays }) => {
    const amountBigInt = parseUnits(amount, abxToken.decimals);
    const currentDate = /* @__PURE__ */ new Date();
    const daysUntilNextEpoch = getDaysUntilNextEpoch(currentDate);
    let epochs;
    if (lockDurationInDays <= daysUntilNextEpoch) {
      epochs = 1;
    } else {
      const daysAfterFirstEpoch = lockDurationInDays - daysUntilNextEpoch;
      const additionalEpochs = Math.ceil(daysAfterFirstEpoch / 7);
      epochs = 1 + additionalEpochs;
    }
    const SECONDS_PER_WEEK = 7 * 24 * 60 * 60;
    const lockDurationInSeconds = BigInt(epochs * SECONDS_PER_WEEK);
    return writeContract({
      address: VOTING_ESCROW_ADDRESS,
      abi: VOTING_ESCROW_ABI,
      functionName: "createLock",
      args: [amountBigInt, lockDurationInSeconds]
    });
  }, [writeContract, abxToken]);
  const increaseLockAmount = useCallback(async ({ tokenId, amount }) => {
    const amountBigInt = parseUnits(amount, abxToken.decimals);
    return writeContract({
      address: VOTING_ESCROW_ADDRESS,
      abi: VOTING_ESCROW_ABI,
      functionName: "increaseAmount",
      args: [BigInt(tokenId), amountBigInt]
    });
  }, [writeContract, abxToken]);
  const extendLockTime = useCallback(async ({ tokenId, lockDurationInDays }) => {
    const lockDurationInSeconds = BigInt(lockDurationInDays * 24 * 60 * 60);
    return writeContract({
      address: VOTING_ESCROW_ADDRESS,
      abi: VOTING_ESCROW_ABI,
      functionName: "increaseUnlockTime",
      args: [BigInt(tokenId), lockDurationInSeconds]
    });
  }, [writeContract]);
  const mergeLocks = useCallback(async ({ fromTokenId, toTokenId }) => {
    return writeContract({
      address: VOTING_ESCROW_ADDRESS,
      abi: VOTING_ESCROW_ABI,
      functionName: "merge",
      args: [BigInt(fromTokenId), BigInt(toTokenId)]
    });
  }, [writeContract]);
  const withdraw = useCallback(async (tokenId) => {
    return writeContract({
      address: VOTING_ESCROW_ADDRESS,
      abi: VOTING_ESCROW_ABI,
      functionName: "withdraw",
      args: [BigInt(tokenId)]
    });
  }, [writeContract]);
  const lockPermanent = useCallback(async (tokenId) => {
    return writeContract({
      address: VOTING_ESCROW_ADDRESS,
      abi: VOTING_ESCROW_ABI,
      functionName: "lockPermanent",
      args: [BigInt(tokenId)]
    });
  }, [writeContract]);
  const unlockPermanent = useCallback(async (tokenId) => {
    return writeContract({
      address: VOTING_ESCROW_ADDRESS,
      abi: VOTING_ESCROW_ABI,
      functionName: "unlockPermanent",
      args: [BigInt(tokenId)]
    });
  }, [writeContract]);
  const transferLock = useCallback(async ({ tokenId, toAddress }) => {
    if (!account) throw new Error("No account connected");
    return writeContract({
      address: VOTING_ESCROW_ADDRESS,
      abi: VOTING_ESCROW_ABI,
      functionName: "transferFrom",
      args: [account, toAddress, BigInt(tokenId)]
    });
  }, [writeContract, account]);
  const needsApproval = useCallback((amount) => {
    if (!abxAllowance) return true;
    const amountBigInt = parseUnits(amount, abxToken.decimals);
    return abxAllowance < amountBigInt;
  }, [abxAllowance, abxToken]);
  const getFormattedABXBalance = useCallback(() => {
    if (!abxBalance) return "0";
    return formatUnits(abxBalance, abxToken.decimals);
  }, [abxBalance, abxToken]);
  return {
    // Contract interactions
    approveABX,
    createLock,
    createLockBatched,
    increaseLockAmount,
    extendLockTime,
    mergeLocks,
    withdraw,
    lockPermanent,
    unlockPermanent,
    transferLock,
    // Read functions
    needsApproval,
    getFormattedABXBalance,
    // State
    isWritePending,
    isConfirming,
    isSuccess,
    writeError: writeError || receiptError,
    transactionHash: writeData,
    // Data
    abxBalance,
    abxAllowance,
    lockCount,
    // Batching support
    supportsEip5792,
    // Refetch functions
    refetchAllowance,
    refetchLockCount
  };
}
